// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var XD = [-6.6, 9.4], YD = [-3.7, 3.7];
var frame = setPlotFrame({ xDomain: XD, yDomain: YD, margin: 12, draw: figDraw });

var HO = 1.4;          // object height (world units, f = 1)
var LH = 2.5;          // lens half height
var EPS = 0.035;       // |d_o - 1| below this  => image at infinity

var C = {
  axis: '#1b1b1b', lens: '#cfe7f3', lensEdge: '#3f92c0',
  obj: '#ef6a60', r1: '#e03127', r2: '#7ea62b', r3: '#7d66c6',
  F: '#d93a2b', dim: '#c8ccd0', meas: '#111'
};

var state = { d: 2.5, overlay: false, sel: 0, step: 0 };
var K = 1, fs = 13;

/* ---------- small helpers ---------- */
function clipSeg(x0, y0, x1, y1) {
  var xmin = 1, ymin = 1, xmax = frame.width - 1, ymax = frame.height - 1;
  var dx = x1 - x0, dy = y1 - y0, t0 = 0, t1 = 1;
  var p = [-dx, dx, -dy, dy], q = [x0 - xmin, xmax - x0, y0 - ymin, ymax - y0];
  for (var i = 0; i < 4; i++) {
    if (p[i] === 0) { if (q[i] < 0) return null; }
    else {
      var r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
  }
  return [x0 + t0 * dx, y0 + t0 * dy, x0 + t1 * dx, y0 + t1 * dy];
}

function head(g, x, y, ang, size, color, op) {
  var pts = [[0, 0], [-size, size * 0.46], [-size, -size * 0.46]];
  var c = Math.cos(ang), s = Math.sin(ang);
  var str = pts.map(function (p) {
    return (x + p[0] * c - p[1] * s) + ',' + (y + p[0] * s + p[1] * c);
  }).join(' ');
  return g.polygon(str).fill({ color: color, opacity: op == null ? 1 : op });
}

function txt(g, s, x, y, o) {
  o = o || {};
  var t = g.plain(String(s));
  t.font({ family: 'sans-serif', size: o.size || fs, weight: o.weight || 'normal' });
  t.fill(o.fill || '#111');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'central' });
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2, (o.size || fs) * 0.30), 'stroke-linejoin': 'round' });
  }
  return t;
}

function labelSub(g, main, sub, x, y, o) {
  o = o || {};
  var s = o.size || fs;
  txt(g, main, x, y, { size: s, anchor: 'end', fill: o.fill, weight: o.weight });
  txt(g, sub, x + s * 0.06, y + s * 0.27, { size: s * 0.7, anchor: 'start', fill: o.fill, weight: o.weight });
}

function wseg(g, p0, p1, color, w, dashed, op) {
  var cl = clipSeg(plotX(p0[0]), plotY(p0[1]), plotX(p1[0]), plotY(p1[1]));
  if (!cl) return null;
  var l = g.line(cl[0], cl[1], cl[2], cl[3]).stroke({
    color: color, width: w, linecap: 'round', opacity: op == null ? 1 : op
  });
  if (dashed) l.attr('stroke-dasharray', (5.5 * K) + ',' + (4.5 * K));
  return l;
}

function segHeadAtT(g, p0, p1, t, color, size) {
  var wx = p0[0] + (p1[0] - p0[0]) * t, wy = p0[1] + (p1[1] - p0[1]) * t;
  var x = plotX(wx), y = plotY(wy);
  if (x < 4 || x > frame.width - 4 || y < 4 || y > frame.height - 4) return;
  var ang = Math.atan2(plotY(p1[1]) - plotY(p0[1]), plotX(p1[0]) - plotX(p0[0]));
  head(g, x, y, ang, size, color);
}

function segHeadAtX(g, p0, p1, wx, color, size) {
  if (Math.abs(p1[0] - p0[0]) < 1e-9) return;
  var t = (wx - p0[0]) / (p1[0] - p0[0]);
  if (t < 0.03 || t > 0.99) return;
  segHeadAtT(g, p0, p1, t, color, size);
}

function interactive(el, tip, title, body, onClick) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () {
    if (onClick) onClick();
    if (title) showPopup(title, body);
  });
}

function vArrow(g, wx, wy, color, width, op) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var dir = (y1 < y0) ? -1 : 1;
  var hs = 9 * K;
  g.line(x, y0, x, y1 - dir * hs * 0.35).stroke({ color: color, width: width, linecap: 'butt', opacity: op == null ? 1 : op });
  head(g, x, y1, dir < 0 ? -Math.PI / 2 : Math.PI / 2, hs, color, op);
}

function bracket(g, wx0, wx1, wy, main, sub, note) {
  var x0 = plotX(wx0), x1 = plotX(wx1), y = plotY(wy);
  var tick = 7 * K, hs = 7 * K;
  g.line(x0, y - tick, x0, y + tick).stroke({ color: C.meas, width: 1.1 * K });
  g.line(x1, y - tick, x1, y + tick).stroke({ color: C.meas, width: 1.1 * K });
  g.line(x0, y, x1, y).stroke({ color: C.meas, width: 1.1 * K });
  if (Math.abs(x1 - x0) > 4 * hs) { head(g, x1, y, 0, hs, C.meas); head(g, x0, y, Math.PI, hs, C.meas); }
  var mid = (x0 + x1) / 2;
  labelSub(g, main, sub, mid + fs * 0.2, y, { size: fs });
  if (note) txt(g, note, mid, y - fs * 1.2, { size: fs * 0.78, fill: '#666' });
}

function vMeasure(g, wx, wy, main, sub, side) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var tick = 6 * K, hs = 7 * K;
  g.line(x - tick, y0, x + tick, y0).stroke({ color: C.meas, width: 1.0 * K });
  g.line(x - tick, y1, x + tick, y1).stroke({ color: C.meas, width: 1.0 * K });
  g.line(x, y0, x, y1).stroke({ color: C.meas, width: 1.1 * K });
  if (Math.abs(y1 - y0) > 4 * hs) {
    head(g, x, y1, y1 < y0 ? -Math.PI / 2 : Math.PI / 2, hs, C.meas);
    head(g, x, y0, y1 < y0 ? Math.PI / 2 : -Math.PI / 2, hs, C.meas);
  }
  labelSub(g, main, sub, x + (side > 0 ? fs * 1.7 : -fs * 0.75), (y0 + y1) / 2, { size: fs });
}

/* ---------- optics ---------- */
function optics(d) {
  var o = { d: d, ho: HO, valid: Math.abs(d - 1) >= EPS };
  if (o.valid) { o.di = d / (d - 1); o.hi = -HO / (d - 1); o.m = -o.di / d; }
  return o;
}

/* ---------- main render ---------- */
function render() {
  figDraw.clear();
  var W = frame.width, H = frame.height;
  K = Math.max(0.6, Math.min(1.7, Math.min(W / 720, H / 470)));
  fs = Math.max(9, Math.min(18, H * 0.038));

  var d = state.d, O = optics(d);
  var g = figDraw.group();
  var rayW = 2.3 * K, dimW = 1.5 * K, hs = 8 * K;

  /* axis */
  var ax = g.line(plotX(XD[0] + 0.05), plotY(0), plotX(XD[1] - 0.05), plotY(0))
    .stroke({ color: C.axis, width: 1.15 * K });
  interactive(ax, 'Optical axis', 'Optical axis',
    'The reference line through the centre of the lens. Distances d\u2092, d\u1d62 and f are measured along it, and heights are measured from it.');

  /* lens */
  var cx = plotX(0), bl = plotX(0.17) - plotX(0);
  var lens = g.path('M ' + cx + ' ' + plotY(LH) +
    ' Q ' + (cx - 2 * bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(-LH) +
    ' Q ' + (cx + 2 * bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(LH) + ' Z')
    .fill(C.lens).stroke({ color: C.lensEdge, width: 1.6 * K });
  interactive(lens, 'Converging (biconvex) lens', 'The converging lens',
    'A thin biconvex lens bends every incoming ray toward the axis. In the thin-lens idealisation all the bending happens at the single vertical principal plane through the lens centre.');

  /* dashed principal plane */
  g.line(cx, plotY(LH + 0.5), cx, plotY(-LH - 0.5))
    .stroke({ color: '#222', width: 1.0 * K }).attr('stroke-dasharray', (6 * K) + ',' + (5 * K));

  /* focal points */
  [[-1, 'near'], [1, 'far']].forEach(function (p) {
    var dot = g.circle(4.6 * K * 2).fill(C.F).center(plotX(p[0]), plotY(0));
    interactive(dot, 'Focal point F  (' + p[1] + ' side), one focal length f from the lens',
      'Focal point F',
      'Both focal points sit one focal length f from the lens. Rays arriving parallel to the axis leave through the far F; rays that pass through the near F leave parallel to the axis.');
    txt(g, 'F', plotX(p[0]), plotY(0) + fs * 1.15, { size: fs });
  });

  /* ------- rays ------- */
  var L = 60;
  var y3 = O.valid ? O.hi : null;
  var defs = [
    {
      i: 1, color: C.r1,
      segs: [[[-d, HO], [0, HO]], [[0, HO], [L, HO - HO * L]]],
      tip: 'Ray 1: in parallel to the axis \u2192 out through the far focal point F',
      title: 'Ray 1 \u2014 the parallel ray',
      body: 'Any ray that arrives parallel to the optical axis is refracted so that it leaves through the far focal point F. Its outgoing direction is set by f alone, whatever the object distance.'
    },
    {
      i: 2, color: C.r2,
      segs: [[[-d, HO], [0, 0]], [[0, 0], [d * L, -HO * L]]],
      tip: 'Ray 2: straight through the centre of the lens, undeviated',
      title: 'Ray 2 \u2014 the central ray',
      body: 'A ray aimed at the centre of a thin lens passes straight through: the two surfaces are parallel there, so the ray is not deviated. This ray alone fixes the magnification, h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
    }
  ];
  if (y3 !== null) {
    defs.push({
      i: 3, color: C.r3,
      segs: [[[-d, HO], [0, y3]], [[0, y3], [L, y3]]],
      tip: 'Ray 3: through the near focal point F \u2192 out parallel to the axis',
      title: 'Ray 3 \u2014 the focal ray',
      body: 'A ray passing through the near focal point F emerges parallel to the axis (the time-reverse of ray 1). If the object is closer than f, it is the backward extension of the ray that passes through F.'
    });
  }

  defs.forEach(function (R) {
    var dim = (state.sel !== 0 && state.sel !== R.i);
    var col = dim ? C.dim : R.color;
    var w = dim ? dimW : (state.sel === R.i ? rayW * 1.6 : rayW);
    var rg = g.group();
    R.segs.forEach(function (s) { wseg(rg, s[0], s[1], col, w); });
    /* direction arrowheads */
    segHeadAtT(rg, R.segs[0][0], R.segs[0][1], 0.72, col, hs);
    if (R.i === 1) segHeadAtX(rg, R.segs[1][0], R.segs[1][1], 1.9, col, hs);
    if (R.i === 2) segHeadAtX(rg, R.segs[1][0], R.segs[1][1], Math.min(3.0, XD[1] - 1), col, hs);
    if (R.i === 3) segHeadAtX(rg, R.segs[1][0], R.segs[1][1], 3.2, col, hs);
    /* backward (virtual) extensions */
    if (O.valid && O.di < 0) {
      var tipP = [O.di, O.hi];
      wseg(rg, R.i === 1 ? [0, HO] : (R.i === 2 ? [0, 0] : [0, y3]), tipP, col, w * 0.8, true, 0.85);
    }
    if (R.i === 3 && d < 1) wseg(rg, [-d, HO], [-1, 0], col, w * 0.8, true, 0.8);
    /* hit area */
    R.segs.forEach(function (s) {
      var l = wseg(rg, s[0], s[1], '#000', 12 * K, false, 0);
      if (l) interactive(l, R.tip, R.title, R.body, function () { trigger_raySelect(R.i); });
    });
  });

  /* object + image */
  var objHit = g.line(plotX(-d), plotY(0), plotX(-d), plotY(HO)).stroke({ color: '#000', width: 14 * K, opacity: 0 });
  vArrow(g, -d, HO, C.obj, 5 * K);
  interactive(objHit, 'Object, height h\u2092', 'The object',
    'The luminous object of height h\u2092 stands on the axis a distance d\u2092 from the lens. Every point on it sends rays in all directions \u2014 we only trace the three easy ones from its tip.');

  if (O.valid && Math.abs(O.hi) < 3.45 && O.di > XD[0] + 0.3 && O.di < XD[1] - 0.3) {
    var imgHit = g.line(plotX(O.di), plotY(0), plotX(O.di), plotY(O.hi)).stroke({ color: '#000', width: 14 * K, opacity: 0 });
    vArrow(g, O.di, O.hi, C.obj, 5 * K, O.di < 0 ? 0.8 : 1);
    interactive(imgHit,
      (O.di > 0 ? 'Real, inverted image, height h\u1d62' : 'Virtual, upright image (no light actually there)'),
      'The image',
      O.di > 0
        ? 'All three refracted rays cross here, so this is where the image forms. Light really passes through it, so it is real, and it points downward \u2014 inverted \u2014 with h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
        : 'The refracted rays diverge; only their backward extensions meet. The eye sees an enlarged upright virtual image on the object side \u2014 the magnifying-glass case, with d\u1d62 negative.');
    if (O.di > 0) {
      g.circle(5 * K * 2).fill('none').stroke({ color: '#444', width: 1.1 * K })
        .center(plotX(O.di), plotY(O.hi));
    }
  }

  /* ray number labels */
  var labPos = [
    { i: 1, x: -0.55 * d, y: HO + 0.30, c: C.r1 },
    { i: 2, x: -0.45 * d, y: HO * 0.45 + 0.32, c: C.r2 }
  ];
  if (y3 !== null) labPos.push({ i: 3, x: -0.78 * d, y: HO + 0.22 * (y3 - HO) + 0.32, c: C.r3 });
  labPos.forEach(function (p) {
    var dim = (state.sel !== 0 && state.sel !== p.i);
    txt(g, p.i, plotX(p.x), plotY(p.y), { size: fs * 1.08, weight: 'bold', fill: dim ? C.dim : p.c });
  });

  /* selection ring on the governing marker */
  if (state.sel !== 0) {
    var mx = state.sel === 1 ? 1 : (state.sel === 2 ? 0 : -1);
    var ring = g.circle(11 * K * 2).fill('none')
      .stroke({ color: state.sel === 1 ? C.r1 : (state.sel === 2 ? C.r2 : C.r3), width: 1.8 * K })
      .center(plotX(mx), plotY(0));
    ring.attr('stroke-dasharray', (4 * K) + ',' + (3.5 * K));
  }

  /* ------- measurement overlay ------- */
  if (state.overlay) {
    var mg = g.group();
    var hx = XD[0] + 0.42;
    mg.line(plotX(hx), plotY(HO), plotX(-d), plotY(HO))
      .stroke({ color: '#9aa0a6', width: 0.8 * K }).attr('stroke-dasharray', (3 * K) + ',' + (3 * K));
    vMeasure(mg, hx, HO, 'h', 'o', 1);

    bracket(mg, 0, 1, 0.62, 'f', '', null);
    bracket(mg, -d, 0, -2.95, 'd', 'o', null);

    if (O.valid) {
      if (O.di > 0) {
        var xEnd = Math.min(O.di, XD[1] - 0.4);
        bracket(mg, 0, xEnd, -2.95, 'd', 'i', O.di > XD[1] - 0.4 ? ('d\u1d62 = ' + O.di.toFixed(2) + 'f \u2014 off frame') : null);
      } else {
        bracket(mg, Math.max(O.di, XD[0] + 0.4), 0, -3.38, 'd', 'i', 'negative (virtual)');
      }
      if (Math.abs(O.hi) < 3.3 && O.di > XD[0] + 0.3 && O.di < XD[1] - 0.9) {
        vMeasure(mg, O.di + 0.5, O.hi, 'h', 'i', 1);
      }
    }

    /* compact numeric readout, top-left whitespace */
    var rx = plotX(XD[0] + 0.25), ry = plotY(3.32), lh = fs * 1.35;
    var lines = [
      ['d', 'o', '= ' + d.toFixed(2) + ' f'],
      ['d', 'i', O.valid ? ('= ' + O.di.toFixed(2) + ' f') : '\u2192 \u221e'],
      ['m', '', O.valid ? ('= ' + O.m.toFixed(2) + (O.m < 0 ? '  (real, inverted)' : '  (virtual, upright)')) : '  (image at infinity)']
    ];
    lines.forEach(function (L2, k) {
      var y = ry + k * lh;
      txt(mg, L2[0], rx, y, { anchor: 'start', size: fs * 0.95 });
      if (L2[1]) txt(mg, L2[1], rx + fs * 0.62, y + fs * 0.25, { anchor: 'start', size: fs * 0.68 });
      txt(mg, L2[2], rx + fs * 1.15, y, { anchor: 'start', size: fs * 0.95 });
    });
  }

  updateReadout(O);
}

/* ---------- UI plumbing ---------- */
function updateReadout(O) {
  var el = document.getElementById('readout');
  if (!el) return;
  if (!O.valid) {
    el.innerHTML = 'd<sub>o</sub> = ' + O.d.toFixed(2) + ' f &nbsp; d<sub>i</sub> &rarr; &infin;<br>Refracted rays are parallel &mdash; no image forms.';
    return;
  }
  var type = O.di > 0 ? 'real, inverted' : 'virtual, upright';
  var size = Math.abs(O.m) > 1 ? 'enlarged' : (Math.abs(O.m) < 1 ? 'reduced' : 'same size');
  el.innerHTML = '1/d<sub>o</sub> + 1/d<sub>i</sub> = 1/f<br>' +
    'd<sub>o</sub> = ' + O.d.toFixed(2) + ' f &nbsp; d<sub>i</sub> = ' + O.di.toFixed(2) + ' f<br>' +
    'm = &minus;d<sub>i</sub>/d<sub>o</sub> = ' + O.m.toFixed(2) + '<br>' + type + ', ' + size;
}

function update_objectDistance(v) { state.d = +v; render(); }
function toggle_measureOverlay(on) { state.overlay = !!on; render(); }
function trigger_raySelect(n) {
  state.sel = (state.sel === n && n !== 0) ? 0 : n;
  syncRayButtons();
  render();
}
function syncRayButtons() {
  for (var i = 0; i <= 3; i++) {
    var b = document.getElementById('rayBtn' + i);
    if (b) b.className = (state.sel === i) ? 'active' : '';
  }
}

var STEPS = [
  {
