  var sl = document.getElementById('objectDistanceInput');
  sl.value = s.state.objectDistance;
  document.getElementById('objectDistanceVal').value = (+s.state.objectDistance).toFixed(2);
  state.d = +s.state.objectDistance;
  var ov = (s.state.measureOverlay === 'Measurement overlay');
  document.getElementById('measureOverlayInput').checked = ov;
  state.overlay = ov;
  state.sel = 0; syncRayButtons();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + STEPS.length + '  ' + s.title;
  render();
}
function nextStep() { setStep(state.step + 1); }
function prevStep() { setStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Three easy-to-draw principal rays from a point on the object all converge at one point after a converging lens, and that crossing point locates and sizes the real, inverted image described by 1/d_o + 1/d_i = 1/f.
KEY INSIGHT (what students should walk away understanding): Three rays drawn by three different simple rules meet at one point — that single intersection is the image, giving its position, size and orientation without any algebra.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
