  var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
  var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
  return { w: Math.max(60, c.clientWidth - px), h: Math.max(60, c.clientHeight - py) };
}

function optics(d) {
  var o = { d: d, ho: HO, valid: Math.abs(d - 1) >= EPS };
  if (o.valid) { o.di = d / (d - 1); o.hi = -HO / (d - 1); o.m = -o.di / d; }
  return o;
}

/* isotropic frame: keeps the source-like scale at the default state */
function setupFrame(O) {
  var sz = innerSize(), m = 10, d = state.d;
  var xl = Math.min(-3.95, -d - 0.62);
  var xr = 2.85, yt = 1.95, yb = -2.20;
  if (O.valid && O.di > 0) xr = Math.max(xr, Math.min(O.di + 0.8, 4.7));
  if (O.valid && O.di < 0) xl = Math.min(xl, O.di - 0.45);
  if (O.valid && O.hi > 0) yt = Math.max(yt, Math.min(O.hi + 0.35, 3.4));
  var aw = Math.max(40, sz.w - 2 * m), ah = Math.max(40, sz.h - 2 * m);
  var s = Math.min(aw / (xr - xl), ah / (yt - yb));
  PPF = s;
  var hx = aw / (2 * s), hy = ah / (2 * s);
  var cx = (xl + xr) / 2, cy = (yt + yb) / 2;
  frame = setPlotFrame({
    xDomain: [cx - hx, cx + hx], yDomain: [cy - hy, cy + hy],
    margin: m, draw: figDraw
  });
}

/* ---------- primitives ---------- */
function clipSeg(x0, y0, x1, y1) {
  var xmin = 1, ymin = 1, xmax = frame.width - 1, ymax = frame.height - 1;
  var dx = x1 - x0, dy = y1 - y0, t0 = 0, t1 = 1;
  var p = [-dx, dx, -dy, dy], q = [x0 - xmin, xmax - x0, y0 - ymin, ymax - y0];
  for (var i = 0; i < 4; i++) {
    if (p[i] === 0) { if (q[i] < 0) return null; }
    else {
      var r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
  }
  return [x0 + t0 * dx, y0 + t0 * dy, x0 + t1 * dx, y0 + t1 * dy];
}

function head(g, x, y, ang, size, color, op) {
  var pts = [[0, 0], [-size, size * 0.45], [-size, -size * 0.45]];
  var c = Math.cos(ang), s = Math.sin(ang);
  return g.polygon(pts.map(function (p) {
    return (x + p[0] * c - p[1] * s) + ',' + (y + p[0] * s + p[1] * c);
  }).join(' ')).fill({ color: color, opacity: op == null ? 1 : op });
}

function txt(g, s, x, y, o) {
  o = o || {};
  var size = o.size || fs;
  var t = g.plain(String(s));
  t.font({ family: o.family || 'sans-serif', size: size, weight: o.weight || 'normal', style: o.italic ? 'italic' : 'normal' });
  t.fill(o.fill || '#111');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'central' });
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2, size * 0.28), 'stroke-linejoin': 'round' });
  }
  return t;
}

/* inline math label "d" + subscript, centred as one unit (screen px) */
function mathLabel(g, main, sub, x, y, size, o) {
  o = o || {};
  var wm = size * 0.58 * String(main).length;
  var ws = sub ? size * 0.68 * 0.58 * String(sub).length : 0;
  var total = wm + ws, x0;
  var anchor = o.anchor || 'middle';
  if (anchor === 'middle') x0 = x - total / 2;
  else if (anchor === 'end') x0 = x - total;
  else x0 = x;
  txt(g, main, x0, y, { size: size, anchor: 'start', italic: true, family: MATHF, fill: o.fill, weight: o.weight });
  if (sub) txt(g, sub, x0 + wm, y + size * 0.30, { size: size * 0.68, anchor: 'start', italic: true, family: MATHF, fill: o.fill, weight: o.weight });
}

function wseg(g, p0, p1, color, w, dashed, op) {
  var cl = clipSeg(plotX(p0[0]), plotY(p0[1]), plotX(p1[0]), plotY(p1[1]));
  if (!cl) return null;
  var l = g.line(cl[0], cl[1], cl[2], cl[3]).stroke({
    color: color, width: w, linecap: 'round', opacity: op == null ? 1 : op
  });
  if (dashed) l.attr('stroke-dasharray', (5 * K) + ',' + (4 * K));
  return l;
}

function segHeadAtT(g, p0, p1, t, color, size) {
  var wx = p0[0] + (p1[0] - p0[0]) * t, wy = p0[1] + (p1[1] - p0[1]) * t;
  var x = plotX(wx), y = plotY(wy);
  if (x < 6 || x > frame.width - 6 || y < 6 || y > frame.height - 6) return;
  var ang = Math.atan2(plotY(p1[1]) - plotY(p0[1]), plotX(p1[0]) - plotX(p0[0]));
  head(g, x, y, ang, size, color);
}
function segHeadAtX(g, p0, p1, wx, color, size) {
  if (Math.abs(p1[0] - p0[0]) < 1e-9) return;
  var t = (wx - p0[0]) / (p1[0] - p0[0]);
  if (t < 0.04 || t > 0.99) return;
  segHeadAtT(g, p0, p1, t, color, size);
}

function interactive(el, tip, title, body, onClick) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { if (onClick) onClick(); if (title) showPopup(title, body); });
}

function vArrow(g, wx, wy, color, width, op) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var dir = (y1 < y0) ? -1 : 1, hs = 0.115 * PPF;
  g.line(x, y0, x, y1 - dir * hs * 0.4).stroke({ color: color, width: width, linecap: 'butt', opacity: op == null ? 1 : op });
  head(g, x, y1, dir < 0 ? -Math.PI / 2 : Math.PI / 2, hs, color, op);
}

/* ---------- dimension marks ---------- */
function hBracket(g, wx0, wx1, wy, main, sub, note) {
  var x0 = plotX(wx0), x1 = plotX(wx1), y = plotY(wy);
  var tick = 0.10 * PPF, hs = 0.075 * PPF, w = 1.15 * K;
  g.line(x0, y - tick, x0, y + tick).stroke({ color: C.dim, width: w });
  g.line(x1, y - tick, x1, y + tick).stroke({ color: C.dim, width: w });
  g.line(x0, y, x1, y).stroke({ color: C.dim, width: w });
  if (Math.abs(x1 - x0) > 3.2 * hs) { head(g, x1, y, 0, hs, C.dim); head(g, x0, y, Math.PI, hs, C.dim); }
  mathLabel(g, main, sub, (x0 + x1) / 2, y - fs * 0.72, fs * 1.05, {});
  if (note) txt(g, note, (x0 + x1) / 2, y + fs * 0.85, { size: fs * 0.62, fill: '#666' });
}

function vMeasure(g, wx, wy, main, sub) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var tick = 0.085 * PPF, hs = 0.075 * PPF, w = 1.15 * K;
  g.line(x - tick, y0, x + tick, y0).stroke({ color: C.dim, width: w });
  g.line(x - tick, y1, x + tick, y1).stroke({ color: C.dim, width: w });
  g.line(x, y0, x, y1).stroke({ color: C.dim, width: w });
  if (Math.abs(y1 - y0) > 3.2 * hs) {
    head(g, x, y1, y1 < y0 ? -Math.PI / 2 : Math.PI / 2, hs, C.dim);
    head(g, x, y0, y1 < y0 ? Math.PI / 2 : -Math.PI / 2, hs, C.dim);
  }
  mathLabel(g, main, sub, x + 0.20 * PPF, (y0 + y1) / 2, fs * 1.05, { anchor: 'start' });
}

/* ---------- main render ---------- */
function render() {
  var d = state.d, O = optics(d);
  setupFrame(O);
  figDraw.clear();

  var XD = frame.xDomain, YD = frame.yDomain;
  K = Math.max(0.5, Math.min(2.0, PPF / 95));
  fs = Math.max(10, Math.min(26, PPF * 0.205));

  var gBase = figDraw.group(), gRay = figDraw.group(),
    gMark = figDraw.group(), gLab = figDraw.group(), gHit = figDraw.group();

  var rayW = 0.024 * PPF, dimW = 0.017 * PPF, hs = 0.09 * PPF;

  /* optical axis */
  var ax = gBase.line(plotX(XD[0] + 0.04), plotY(0), plotX(XD[1] - 0.04), plotY(0))
    .stroke({ color: C.axis, width: 1.15 * K });
  interactive(ax, 'Optical axis', 'Optical axis',
    'The reference line through the centre of the lens. Distances d\u2092, d\u1d62 and f are measured along it; heights h\u2092 and h\u1d62 are measured from it.');

  /* fat biconvex lens */
  var grad = figDraw.gradient('linear', function (add) {
    add.stop(0, '#eef8fd'); add.stop(0.45, '#bfe1f2'); add.stop(1, '#93c8e2');
  });
  var cx = plotX(0), bl = plotX(0.60) - plotX(0);
  var lens = gBase.path('M ' + cx + ' ' + plotY(LH) +
    ' Q ' + (cx - bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(-LH) +
    ' Q ' + (cx + bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(LH) + ' Z')
    .fill(grad).stroke({ color: C.lensEdge, width: 1.7 * K });
  interactive(lens, 'Converging (biconvex) lens', 'The converging lens',
    'A thin biconvex lens bends every incoming ray toward the axis. In the thin-lens idealisation all of the bending is drawn at the single vertical principal plane through the lens centre.');

  /* dashed principal plane, trimmed to the lens height */
  gBase.line(cx, plotY(LH * 1.02), cx, plotY(-LH * 1.02))
    .stroke({ color: '#222', width: 1.0 * K }).attr('stroke-dasharray', (0.07 * PPF) + ',' + (0.06 * PPF));

  /* ---------- rays ---------- */
  var xe = XD[1] + 0.6;
  var y3 = O.valid ? O.hi : null;
  var defs = [
    {
      i: 1, color: C.r1,
      segs: [[[-d, HO], [0, HO]], [[0, HO], [xe, HO * (1 - xe)]]],
      tip: 'Ray 1: in parallel to the axis \u2192 out through the far focal point F',
      title: 'Ray 1 \u2014 the parallel ray',
      body: 'A ray arriving parallel to the optical axis is refracted so that it leaves through the far focal point F. Its outgoing direction depends only on f, not on where the object sits.'
    },
    {
      i: 2, color: C.r2,
      segs: [[[-d, HO], [0, 0]], [[0, 0], [xe, -HO * xe / d]]],
      tip: 'Ray 2: straight through the centre of the lens, undeviated',
      title: 'Ray 2 \u2014 the central ray',
      body: 'A ray aimed at the centre of a thin lens passes straight through: the surfaces are parallel there, so it is not deviated. This ray alone fixes the magnification, h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
    }
  ];
  if (y3 !== null) {
    defs.push({
      i: 3, color: C.r3,
      segs: [[[-d, HO], [0, y3]], [[0, y3], [xe, y3]]],
      tip: 'Ray 3: through the near focal point F \u2192 out parallel to the axis',
      title: 'Ray 3 \u2014 the focal ray',
      body: 'A ray that passes through the near focal point F emerges parallel to the axis \u2014 the exact time-reverse of ray 1. If the object is inside f, it is the backward extension of the ray that passes through F.'
    });
  }

  defs.forEach(function (R) {
    var dim = (state.sel !== 0 && state.sel !== R.i);
    var col = dim ? C.gray : R.color;
    var w = dim ? dimW : (state.sel === R.i ? rayW * 1.55 : rayW);
    R.segs.forEach(function (s) { wseg(gRay, s[0], s[1], col, w); });
    segHeadAtT(gRay, R.segs[0][0], R.segs[0][1], 0.66, col, hs);
    if (R.i === 1) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(1.55, XD[1] - 0.45), col, hs);
    if (R.i === 2) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(2.15, XD[1] - 0.30), col, hs);
    if (R.i === 3) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(1.25, XD[1] - 0.30), col, hs);
    /* virtual-image backward extensions */
    if (O.valid && O.di < 0) {
      var start = (R.i === 1) ? [0, HO] : (R.i === 2 ? [0, 0] : [0, y3]);
      wseg(gRay, start, [O.di, O.hi], col, w * 0.8, true, 0.9);
    }
    if (R.i === 3 && d < 1) wseg(gRay, [-d, HO], [-1, 0], col, w * 0.8, true, 0.8);
    /* hit strips */
    R.segs.forEach(function (s) {
      var l = wseg(gHit, s[0], s[1], '#000', 0.14 * PPF, false, 0);
      if (l) interactive(l, R.tip, R.title, R.body, function () { trigger_raySelect(R.i); });
    });
  });

  /* focal points */
  [[-1, 'near', -0.14], [1, 'far', -0.13]].forEach(function (p) {
    var dot = gMark.circle(2 * Math.max(2.6, 0.045 * PPF)).fill(C.F).center(plotX(p[0]), plotY(0));
    interactive(dot, 'Focal point F (' + p[1] + ' side) \u2014 one focal length f from the lens',
      'Focal point F',
      'Both focal points lie one focal length f from the lens. Rays arriving parallel to the axis leave through the far F; rays passing through the near F leave parallel to the axis.');
    txt(gMark, 'F', plotX(p[0] + p[2]), plotY(0) - fs * 1.20, { size: fs * 1.15, weight: 'bold', italic: true, family: MATHF });
  });

  /* object */
  vArrow(gMark, -d, HO, C.obj, 0.055 * PPF);
  var objHit = gHit.line(plotX(-d), plotY(0), plotX(-d), plotY(HO))
    .stroke({ color: '#000', width: 0.16 * PPF, opacity: 0 });
  interactive(objHit, 'Object, height h\u2092', 'The object',
    'A luminous object of height h\u2092 stands on the axis a distance d\u2092 from the lens. Every point of it radiates in all directions \u2014 we simply trace the three easiest rays from its tip.');

  /* image */
  var imgVisible = O.valid && Math.abs(O.hi) < (YD[1] - 0.1) &&
    O.di > XD[0] + 0.25 && O.di < XD[1] - 0.25;
  if (imgVisible) {
    vArrow(gMark, O.di, O.hi, C.obj, 0.055 * PPF, O.di < 0 ? 0.85 : 1);
    if (O.di > 0) {
      gMark.circle(2 * 0.055 * PPF).fill('none').stroke({ color: '#444', width: 1.1 * K })
        .center(plotX(O.di), plotY(O.hi));
    }
    var imgHit = gHit.line(plotX(O.di), plotY(0), plotX(O.di), plotY(O.hi))
      .stroke({ color: '#000', width: 0.16 * PPF, opacity: 0 });
    interactive(imgHit,
      (O.di > 0 ? 'Real, inverted image, height h\u1d62' : 'Virtual, upright image (no light actually there)'),
      'The image',
      O.di > 0
        ? 'All three refracted rays cross here, so this single point is the image. Light really passes through it, so the image is real, and it points downward \u2014 inverted \u2014 with h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
        : 'The refracted rays diverge; only their dashed backward extensions meet. The eye sees an enlarged upright virtual image on the object side \u2014 the magnifying-glass case, with d\u1d62 negative.');
  }

  /* selection ring on the governing marker */
  if (state.sel !== 0) {
    var mx = state.sel === 1 ? 1 : (state.sel === 2 ? 0 : -1);
    gMark.circle(2 * 0.13 * PPF).fill('none')
      .stroke({ color: state.sel === 1 ? C.r1 : (state.sel === 2 ? C.r2 : C.r3), width: 1.8 * K })
      .center(plotX(mx), plotY(0))
      .attr('stroke-dasharray', (0.05 * PPF) + ',' + (0.045 * PPF));
  }

  /* ---------- ray numerals (kept clear of the object arrow) ---------- */
  var labs = [{ i: 1, x: -0.50 * d, y: HO + 0.20, c: C.r1 },
  { i: 2, x: -0.45 * d, y: 0.45 * HO + 0.21, c: C.r2 }];
  if (y3 !== null) {
    if (d > 1) {
      var lx3 = -1 - 0.55 * (d - 1);
      var ly3 = -(HO / (d - 1)) * (lx3 + 1) - 0.20;
      labs.push({ i: 3, x: lx3, y: ly3, c: C.r3 });
    } else {
      labs.push({ i: 3, x: -0.55 * d, y: HO + 0.45 * (y3 - HO) - 0.06, c: C.r3 });
    }
  }
  labs.forEach(function (p) {
    var dim = (state.sel !== 0 && state.sel !== p.i);
    txt(gLab, p.i, plotX(p.x), plotY(p.y),
      { size: fs * 1.22, weight: 'bold', fill: dim ? C.gray : p.c });
  });

  /* ---------- dimension annotations ---------- */
  if (state.ann) {
    var mg = gLab.group();

    /* h_o */
    var xho = XD[0] + 0.30;
    mg.line(plotX(xho), plotY(HO), plotX(-d), plotY(HO))
      .stroke({ color: '#9aa0a6', width: 0.8 * K }).attr('stroke-dasharray', (0.035 * PPF) + ',' + (0.035 * PPF));
    vMeasure(mg, xho, HO, 'h', 'o');

    /* f, from lens centre to the far focal point */
    hBracket(mg, 0, 1, 0.30, 'f', '', null);

    var yD1 = -1.75, yD2 = -2.05;
    if (O.valid && O.di < 0) {
      hBracket(mg, -d, 0, yD1, 'd', 'o', null);
      hBracket(mg, Math.max(O.di, XD[0] + 0.25), 0, yD2, 'd', 'i', 'negative (virtual)');
    } else {
      hBracket(mg, -d, 0, yD1, 'd', 'o', null);
      if (O.valid) {
        var xEnd = Math.min(O.di, XD[1] - 0.22);
        hBracket(mg, 0, xEnd, yD1, 'd', 'i',
          (O.di > XD[1] - 0.22) ? ('= ' + O.di.toFixed(1) + ' f \u2014 beyond the frame') : null);
      }
    }

    /* h_i */
    if (imgVisible) vMeasure(mg, O.di + 0.26, O.hi, 'h', 'i');
  }

  updateReadout(O);
}

/* ---------- UI plumbing ---------- */
function updateReadout(O) {
  var el = document.getElementById('readout');
  if (!el) return;
  if (!O.valid) {
    el.innerHTML = 'd<sub>o</sub> = ' + O.d.toFixed(2) + ' f &nbsp; d<sub>i</sub> &rarr; &infin;<br>Refracted rays are parallel &mdash; no image forms.';
    return;
  }
  var type = O.di > 0 ? 'real, inverted' : 'virtual, upright';
  var size = Math.abs(O.m) > 1 ? 'enlarged' : (Math.abs(O.m) < 1 ? 'reduced' : 'same size');
  el.innerHTML = '1/d<sub>o</sub> + 1/d<sub>i</sub> = 1/f<br>' +
    'f = 1.00 &nbsp; d<sub>o</sub> = ' + O.d.toFixed(2) + ' f<br>' +
    'd<sub>i</sub> = ' + O.di.toFixed(2) + ' f<br>' +
    'm = &minus;d<sub>i</sub>/d<sub>o</sub> = ' + O.m.toFixed(2) + '<br>' + type + ', ' + size;
}

function update_objectDistance(v) { state.d = +v; render(); }
function toggle_annotations(on) { state.ann = !!on; render(); }
function trigger_raySelect(n) {
  state.sel = (state.sel === n && n !== 0) ? 0 : n;
  syncRayButtons();
  render();
}
function syncRayButtons() {
  for (var i = 0; i <= 3; i++) {
    var b = document.getElementById('rayBtn' + i);
    if (b) b.className = (state.sel === i) ? 'active' : '';
  }
}

var STEPS = [
  {
    title: 'The measured figure',
    narration: 'The full textbook figure: an object of height h\u2092, a fat biconvex lens with its dashed principal plane, focal points F one focal length f on each side, brackets for f, d\u2092 and d\u1d62, and the inverted image of height h\u1d62.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Three rays, three rules',
    narration: 'Rays 1, 2 and 3 all leave the same point at the object\u2019s tip. Click any one (in the figure or with the buttons) to isolate it: parallel-then-through-F, straight-through-the-centre, or through-F-then-parallel.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Strip the annotations',
    narration: 'Hide the brackets and height arrows and only the rays remain \u2014 yet they still cross at exactly the same point. The image location is a consequence of the geometry, not of the labels.',
    state: { objectDistance: 2.5, annotations: 'Hidden' }
  },
  {
    title: 'Bring the measurements back',
    narration: 'Restore the overlay and read the numbers: h\u1d62/h\u2092 equals \u2212d\u1d62/d\u2092, and the three distances satisfy 1/d\u2092 + 1/d\u1d62 = 1/f.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Push the object far away',
    narration: 'With the object far from the lens the rays converge just beyond the far focal point: d\u1d62 shrinks toward f and the inverted image becomes small.',
    state: { objectDistance: 5, annotations: 'Shown' }
  },
  {
    title: 'Slide it toward the focal point',
    narration: 'As d\u2092 approaches f the refracted rays become nearly parallel, d\u1d62 shoots off to the right and the inverted image grows enormous.',
    state: { objectDistance: 1.15, annotations: 'Shown' }
  },
  {
    title: 'Inside the focal point',
    narration: 'Closer than f, the refracted rays diverge; their dashed backward extensions meet at an upright, magnified virtual image on the object side \u2014 the magnifying-glass case, with d\u1d62 now negative.',
    state: { objectDistance: 0.55, annotations: 'Shown' }
  }
];

function setStep(i) {
  state.step = (i + STEPS.length) % STEPS.length;
  var s = STEPS[state.step];
  document.getElementById('objectDistanceInput').value = s.state.objectDistance;
  document.getElementById('objectDistanceVal').value = (+s.state.objectDistance).toFixed(2);
  state.d = +s.state.objectDistance;
  var ann = (s.state.annotations !== 'Hidden');
  document.getElementById('annotationsInput').checked = ann;
  state.ann = ann;
  state.sel = 0; syncRayButtons();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + STEPS.length + '  ' + s.title;
  render();
}
function nextStep() { setStep(state.step + 1); }
function prevStep() { setStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Three easy-to-draw principal rays from a point on the object all converge at one point after a converging lens, and that crossing point locates and sizes the real, inverted image described by 1/d_o + 1/d_i = 1/f.
KEY INSIGHT (what students should walk away understanding): Three rays drawn by three different simple rules meet at one point — that single intersection is the image, giving its position, size and orientation without any algebra.
DEMO STEPS: 7 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Three easy-to-draw principal rays from a point on the object all converge at one point after a converging lens, and that crossing point locates and sizes the real, inverted image described by 1/d_o + 1/d_i = 1/f.",
  "figureType": "diagram",
  "elements": [
    "Horizontal black optical axis spanning the full canvas width, with the plotted world domain tightened to roughly x = -4 to +5 focal lengths and y = -3 to +3 so object, lens, rays and image fill the frame at textbook scale",
    "Fat biconvex lens centered on the axis: pale blue fill, darker blue outline, drawn with a large bulge control offset so the two convex faces visibly swell (thick lens body, not a sliver)",
    "Short vertical black dashed principal-plane line through the lens center, trimmed to roughly the lens height (does not run the full height of the canvas)",
    "Red upward object arrow standing on the axis left of the lens, thick shaft and solid arrowhead",
    "Vertical double-headed black dimension arrow beside the object labeled h_o (subscript rendered inline, never wrapping)",
    "Red dot on the axis one focal length left of the lens, labeled F in large bold black type below the axis",
    "Red dot on the axis one focal length right of the lens, labeled F in large bold black type below the axis",
    "Horizontal double-headed bracket from lens center to the right focal point labeled f",
    "Ray 1 (red): from the object tip parallel to the axis, refracting at the principal plane and passing through the far focal point, continuing down-right past the image",
    "Ray 2 (green): from the object tip straight through the lens center undeviated, continuing down-right",
    "Ray 3 (purple): from the object tip through the near focal point, refracting at the lens and emerging parallel to the axis below it",
    "Large bold colored ray numerals: '1' placed above the horizontal incoming segment of ray 1 (well clear of the object arrow), '2' offset along the slanted path of ray 2 between object and lens, '3' offset along the slanted path of ray 3 between object and near focal point",
    "Mid-ray arrowheads on each colored ray showing propagation direction",
    "Short thick red downward image arrow below the axis at the three-ray crossing point (real, inverted image)",
    "Vertical double-headed black dimension arrow beside the image labeled h_i",
    "Horizontal double-headed bracket below the axis from object foot to lens labeled d_o",
    "Horizontal double-headed bracket below the axis from lens to image foot labeled d_i",
    "Compact readout panel showing d_o, d_i, f, magnification m = -d_i/d_o and image type (real/inverted or virtual/upright), with subscripts typeset inline so labels stay on one line",
    "Dashed backward extensions of the refracted rays plus an upright red virtual-image arrow on the object side, shown only when the object sits inside the focal point"
  ],
  "interactions": [
    {
      "id": "objectDistance",
      "type": "slider",
      "teaches": "Moving the object changes where the rays cross: as d_o decreases toward f the image races away from the lens and grows, and inside f the rays diverge into an upright virtual image — the lens equation made visible.",
      "label": "Object distance d_o (units of f)",
      "range": [
        0.4,
        5,
        0.05
      ],
      "default": 2.5
    },
    {
      "id": "raySelect",
      "type": "click",
      "teaches": "Each principal ray obeys one simple rule (parallel-in → through F, straight through the center, through F → parallel-out), yet all three land on the same image point, so any two suffice to construct the image."
    },
    {
      "id": "annotations",
      "type": "toggle",
      "teaches": "The measured drawing IS the algebra: hiding the f, d_o, d_i, h_o and h_i markings leaves the bare ray construction, showing that the geometry alone already determines every quantity in the lens and magnification equations.",
      "label": "Dimension annotations",
      "options": [
        "Shown",
        "Hidden"
      ],
      "default": "Shown"
    }
  ],
  "demo_steps": [
    {
      "title": "The measured figure",
      "narration": "The full textbook figure appears as in the source: object arrow of height h_o, fat biconvex lens with its dashed principal plane, focal points F on each side, and brackets for f, d_o and d_i already drawn along with the inverted image of height h_i.",
      "state": {
        "objectDistance": 2.5,
        "annotations": "Shown"
      }
    },
    {
      "title": "Three rays, three rules",
      "narration": "Rays 1, 2 and 3 all leave the same point at the object's tip. Click any one to isolate it: parallel-then-through-F, straight-through-the-center, or through-F-then-parallel.",
      "state": {
        "objectDistance": 2.5,
        "annotations": "Shown"
      }
    },
    {
      "title": "Strip the annotations",
      "narration": "Hide the brackets and height arrows and only the rays remain — yet they still cross at exactly the same point. The image location is a consequence of the geometry, not of the labels.",
      "state": {
        "objectDistance": 2.5,
        "annotations": "Hidden"
      }
    },
    {
      "title": "Bring the measurements back",
      "narration": "Restore the overlay and read the numbers: h_i/h_o equals -d_i/d_o, and the three distances satisfy 1/d_o + 1/d_i = 1/f.",
      "state": {
        "objectDistance": 2.5,
        "annotations": "Shown"
      }
    },
    {
      "title": "Push the object far away",
      "narration": "With the object far from the lens the rays converge just beyond the far focal point: d_i shrinks toward f and the inverted image becomes small.",
      "state": {
        "objectDistance": 5,
        "annotations": "Shown"
      }
    },
    {
      "title": "Slide it toward the focal point",
      "narration": "As d_o approaches f the refracted rays become nearly parallel, d_i shoots off to the right and the inverted image grows enormous.",
      "state": {
        "objectDistance": 1.15,
        "annotations": "Shown"
      }
    },
    {
      "title": "Inside the focal point",
      "narration": "Closer than f, the refracted rays diverge; dashed backward extensions meet at an upright, magnified virtual image on the object side — the magnifying-glass case, with d_i now negative.",
      "state": {
        "objectDistance": 0.6,
        "annotations": "Shown"
      }
    }
  ],
  "keyInsight": "Three rays drawn by three different simple rules meet at one point — that single intersection is the image, giving its position, size and orientation without any algebra.",
  "reconstructionNotes": "Wide landscape layout with a tight world window (about x = -4 to +5 and y = -3 to +3 in focal-length units) so the object, lens, ray fan and image fill the canvas at the same scale as the source. A thin black optical axis runs across the middle. A FAT pale-blue biconvex lens with a darker blue outline sits at the origin — use a generous bezier bulge so the lens body is clearly thick — and a short black dashed vertical line through its center spans only about the lens height. The object is a thick red upward arrow on the axis to the left; a thin black double-headed arrow beside it is labeled h_o. Small red dots sit one focal length left and right of the lens, each labeled F in large bold black type below the axis, and a black double-headed bracket from lens center to the right F is labeled f. Three rays leave the object tip: ray 1 red, horizontal to the lens then sloping down through the right focal point; ray 2 green, straight through the lens center; ray 3 purple, sloping down through the left focal point then horizontal to the right. Their bold numerals use a large font: '1' sits above its horizontal segment near the middle of that run, '2' and '3' sit offset perpendicular to their slanted segments partway between object and lens — none of them crowd the object arrow. Mid-ray arrowheads show direction. The refracted rays cross below the axis right of the lens where a short thick red downward arrow marks the real inverted image, with a labeled h_i dimension arrow beside it. Below the axis, black double-headed brackets span object-to-lens (d_o) and lens-to-image (d_i). Dimension annotations render by DEFAULT; the toggle only hides them, leaving the bare ray construction. All dimension and F labels use an enlarged base font size, and every subscript is typeset inline (single-line labels in both the figure and the control panel). Clicking a ray thickens it to full opacity while the other two fade to light gray and rings the relevant marker (near F, lens center, or far F). In the virtual-image regime the diverging rays gain dashed backward extensions to an upright red image arrow on the object side and the d_i bracket flips to the left and is annotated as negative."
}

The second image above is a screenshot of the PREVIOUS attempt's rendered output (not the source figure) — use it to see exactly what broke.

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span id="demoNarration" style="display:block;margin:0 0 2px 0;font-size:11px;line-height:1.45;color:#222"></span>
<span style="display:flex;align-items:center;gap:6px">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;font-weight:600"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label><span style="white-space:nowrap">Object distance d<sub>o</sub> = <output id="objectDistanceVal">2.50</output>&nbsp;f</span>
  <input id="objectDistanceInput" type="range" min="0.4" max="5" step="0.05" value="2.5"
   oninput="document.getElementById('objectDistanceVal').value=(+this.value).toFixed(2);update_objectDistance(+this.value)"></label>
<label style="flex-direction:row;align-items:center;gap:6px"><input id="annotationsInput" type="checkbox" checked onchange="toggle_annotations(this.checked)"><span style="white-space:nowrap">Dimension annotations (f, d<sub>o</sub>, d<sub>i</sub>, h<sub>o</sub>, h<sub>i</sub>)</span></label>
<span style="display:block;font-size:11px;color:#444">Isolate a principal ray (or click it in the figure):</span>
<span style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="rayBtn0" onclick="trigger_raySelect(0)">All</button>
  <button id="rayBtn1" onclick="trigger_raySelect(1)">Ray 1</button>
  <button id="rayBtn2" onclick="trigger_raySelect(2)">Ray 2</button>
  <button id="rayBtn3" onclick="trigger_raySelect(3)">Ray 3</button>
</span>
<span id="readout" style="display:block;margin:2px 0 0 0;font-size:11px;line-height:1.6;color:#222;font-family:ui-monospace,Consolas,monospace"></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

var HO = 1.16;      // object height in focal lengths (matches source proportions)
var LH = 1.50;      // lens half-height
var EPS = 0.03;

var C = {
  axis: '#111111', lensEdge: '#3d8fbf',
  obj: '#e8564c', r1: '#d6372c', r2: '#7ea62b', r3: '#7d66c6',
  F: '#cf2f24', dim: '#111111', gray: '#d2d5d8'
};
var MATHF = 'Georgia, "Times New Roman", serif';

var state = { d: 2.5, ann: true, sel: 0, step: 0 };
var frame = null, PPF = 85, K = 1, fs = 16;

/* ---------- sizing ---------- */
function innerSize() {
  var c = document.getElementById('container');
  var st = getComputedStyle(c);
  var px = (parseFloat(st.paddingLeft) || 0) + (parseFloat(st.paddingRight) || 0);
  var py = (parseFloat(st.paddingTop) || 0) + (parseFloat(st.paddingBottom) || 0);
  return { w: Math.max(60, c.clientWidth - px), h: Math.max(60, c.clientHeight - py) };
}

function optics(d) {
  var o = { d: d, ho: HO, valid: Math.abs(d - 1) >= EPS };
  if (o.valid) { o.di = d / (d - 1); o.hi = -HO / (d - 1); o.m = -o.di / d; }
  return o;
}

/* isotropic frame: keeps the source-like scale at the default state */
function setupFrame(O) {
  var sz = innerSize(), m = 10, d = state.d;
  var xl = Math.min(-3.95, -d - 0.62);
  var xr = 2.85, yt = 1.95, yb = -2.20;
  if (O.valid && O.di > 0) xr = Math.max(xr, Math.min(O.di + 0.8, 4.7));
  if (O.valid && O.di < 0) xl = Math.min(xl, O.di - 0.45);
  if (O.valid && O.hi > 0) yt = Math.max(yt, Math.min(O.hi + 0.35, 3.4));
  var aw = Math.max(40, sz.w - 2 * m), ah = Math.max(40, sz.h - 2 * m);
  var s = Math.min(aw / (xr - xl), ah / (yt - yb));
  PPF = s;
  var hx = aw / (2 * s), hy = ah / (2 * s);
  var cx = (xl + xr) / 2, cy = (yt + yb) / 2;
  frame = setPlotFrame({
    xDomain: [cx - hx, cx + hx], yDomain: [cy - hy, cy + hy],
    margin: m, draw: figDraw
  });
}

/* ---------- primitives ---------- */
function clipSeg(x0, y0, x1, y1) {
  var xmin = 1, ymin = 1, xmax = frame.width - 1, ymax = frame.height - 1;
  var dx = x1 - x0, dy = y1 - y0, t0 = 0, t1 = 1;
  var p = [-dx, dx, -dy, dy], q = [x0 - xmin, xmax - x0, y0 - ymin, ymax - y0];
  for (var i = 0; i < 4; i++) {
    if (p[i] === 0) { if (q[i] < 0) return null; }
    else {
      var r = q[i] / p[i];
      if (p[i] < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
  }
  return [x0 + t0 * dx, y0 + t0 * dy, x0 + t1 * dx, y0 + t1 * dy];
}

function head(g, x, y, ang, size, color, op) {
  var pts = [[0, 0], [-size, size * 0.45], [-size, -size * 0.45]];
  var c = Math.cos(ang), s = Math.sin(ang);
  return g.polygon(pts.map(function (p) {
    return (x + p[0] * c - p[1] * s) + ',' + (y + p[0] * s + p[1] * c);
  }).join(' ')).fill({ color: color, opacity: op == null ? 1 : op });
}

function txt(g, s, x, y, o) {
  o = o || {};
  var size = o.size || fs;
  var t = g.plain(String(s));
  t.font({ family: o.family || 'sans-serif', size: size, weight: o.weight || 'normal', style: o.italic ? 'italic' : 'normal' });
  t.fill(o.fill || '#111');
  t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', 'dominant-baseline': 'central' });
  if (o.halo !== false) {
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': Math.max(2, size * 0.30), 'stroke-linejoin': 'round' });
  }
  return t;
}

/* inline math label "d" + subscript, centred as one unit (screen px) */
function mathLabel(g, main, sub, x, y, size, o) {
  o = o || {};
  var wm = size * 0.58 * String(main).length;
  var ws = sub ? size * 0.68 * 0.58 * String(sub).length : 0;
  var total = wm + ws, x0;
  var anchor = o.anchor || 'middle';
  if (anchor === 'middle') x0 = x - total / 2;
  else if (anchor === 'end') x0 = x - total;
  else x0 = x;
  txt(g, main, x0, y, { size: size, anchor: 'start', italic: true, family: MATHF, fill: o.fill, weight: o.weight });
  if (sub) txt(g, sub, x0 + wm, y + size * 0.30, { size: size * 0.68, anchor: 'start', italic: true, family: MATHF, fill: o.fill, weight: o.weight });
}

function wseg(g, p0, p1, color, w, dashed, op) {
  var cl = clipSeg(plotX(p0[0]), plotY(p0[1]), plotX(p1[0]), plotY(p1[1]));
  if (!cl) return null;
  var l = g.line(cl[0], cl[1], cl[2], cl[3]).stroke({
    color: color, width: w, linecap: 'round', opacity: op == null ? 1 : op
  });
  if (dashed) l.attr('stroke-dasharray', (5 * K) + ',' + (4 * K));
  return l;
}

function segHeadAtT(g, p0, p1, t, color, size) {
  var wx = p0[0] + (p1[0] - p0[0]) * t, wy = p0[1] + (p1[1] - p0[1]) * t;
  var x = plotX(wx), y = plotY(wy);
  if (x < 6 || x > frame.width - 6 || y < 6 || y > frame.height - 6) return;
  var ang = Math.atan2(plotY(p1[1]) - plotY(p0[1]), plotX(p1[0]) - plotX(p0[0]));
  head(g, x, y, ang, size, color);
}
function segHeadAtX(g, p0, p1, wx, color, size) {
  if (Math.abs(p1[0] - p0[0]) < 1e-9) return;
  var t = (wx - p0[0]) / (p1[0] - p0[0]);
  if (t < 0.04 || t > 0.99) return;
  segHeadAtT(g, p0, p1, t, color, size);
}

function interactive(el, tip, title, body, onClick) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { if (onClick) onClick(); if (title) showPopup(title, body); });
}

function vArrow(g, wx, wy, color, width, op) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var dir = (y1 < y0) ? -1 : 1, hs = 0.115 * PPF;
  g.line(x, y0, x, y1 - dir * hs * 0.4).stroke({ color: color, width: width, linecap: 'butt', opacity: op == null ? 1 : op });
  head(g, x, y1, dir < 0 ? -Math.PI / 2 : Math.PI / 2, hs, color, op);
}

/* ---------- dimension marks ---------- */
function hBracket(g, wx0, wx1, wy, main, sub, labelWorldX) {
  var x0 = plotX(wx0), x1 = plotX(wx1), y = plotY(wy);
  var tick = 0.10 * PPF, hs = 0.075 * PPF, w = 1.15 * K;
  g.line(x0, y - tick, x0, y + tick).stroke({ color: C.dim, width: w });
  g.line(x1, y - tick, x1, y + tick).stroke({ color: C.dim, width: w });
  g.line(x0, y, x1, y).stroke({ color: C.dim, width: w });
  if (Math.abs(x1 - x0) > 3.2 * hs) { head(g, x1, y, 0, hs, C.dim); head(g, x0, y, Math.PI, hs, C.dim); }
  var lx = (labelWorldX == null) ? (x0 + x1) / 2 : plotX(labelWorldX);
  mathLabel(g, main, sub, lx, y - fs * 0.78, fs * 1.05, {});
}

function vMeasure(g, wx, wy, main, sub) {
  var x = plotX(wx), y0 = plotY(0), y1 = plotY(wy);
  var tick = 0.085 * PPF, hs = 0.075 * PPF, w = 1.15 * K;
  g.line(x - tick, y0, x + tick, y0).stroke({ color: C.dim, width: w });
  g.line(x - tick, y1, x + tick, y1).stroke({ color: C.dim, width: w });
  g.line(x, y0, x, y1).stroke({ color: C.dim, width: w });
  if (Math.abs(y1 - y0) > 3.2 * hs) {
    head(g, x, y1, y1 < y0 ? -Math.PI / 2 : Math.PI / 2, hs, C.dim);
    head(g, x, y0, y1 < y0 ? Math.PI / 2 : -Math.PI / 2, hs, C.dim);
  }
  mathLabel(g, main, sub, x + 0.20 * PPF, (y0 + y1) / 2, fs * 1.05, { anchor: 'start' });
}

/* ---------- main render ---------- */
function render() {
  var d = state.d, O = optics(d);
  setupFrame(O);
  figDraw.clear();

  var XD = frame.xDomain, YD = frame.yDomain;
  K = Math.max(0.5, Math.min(2.0, PPF / 95));
  fs = Math.max(10, Math.min(26, PPF * 0.205));

  var gBase = figDraw.group(), gRay = figDraw.group(),
    gMark = figDraw.group(), gLab = figDraw.group(), gHit = figDraw.group();

  var rayW = 0.024 * PPF, dimW = 0.017 * PPF, hs = 0.09 * PPF;

  /* optical axis */
  var ax = gBase.line(plotX(XD[0] + 0.04), plotY(0), plotX(XD[1] - 0.04), plotY(0))
    .stroke({ color: C.axis, width: 1.15 * K });
  interactive(ax, 'Optical axis', 'Optical axis',
    'The reference line through the centre of the lens. Distances d\u2092, d\u1d62 and f are measured along it; heights h\u2092 and h\u1d62 are measured from it.');

  /* fat biconvex lens */
  var grad = figDraw.gradient('linear', function (add) {
    add.stop(0, '#eef8fd'); add.stop(0.45, '#bfe1f2'); add.stop(1, '#93c8e2');
  });
  var cx = plotX(0), bl = plotX(0.60) - plotX(0);
  var lens = gBase.path('M ' + cx + ' ' + plotY(LH) +
    ' Q ' + (cx - bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(-LH) +
    ' Q ' + (cx + bl) + ' ' + plotY(0) + ' ' + cx + ' ' + plotY(LH) + ' Z')
    .fill(grad).stroke({ color: C.lensEdge, width: 1.7 * K });
  interactive(lens, 'Converging (biconvex) lens', 'The converging lens',
    'A thin biconvex lens bends every incoming ray toward the axis. In the thin-lens idealisation all of the bending is drawn at the single vertical principal plane through the lens centre.');

  /* dashed principal plane, trimmed to the lens height */
  gBase.line(cx, plotY(LH * 1.02), cx, plotY(-LH * 1.02))
    .stroke({ color: '#222', width: 1.0 * K }).attr('stroke-dasharray', (0.07 * PPF) + ',' + (0.06 * PPF));

  /* ---------- rays ---------- */
  var xe = XD[1] + 0.6;
  var y3 = O.valid ? O.hi : null;
  var defs = [
    {
      i: 1, color: C.r1,
      segs: [[[-d, HO], [0, HO]], [[0, HO], [xe, HO * (1 - xe)]]],
      tip: 'Ray 1: in parallel to the axis \u2192 out through the far focal point F',
      title: 'Ray 1 \u2014 the parallel ray',
      body: 'A ray arriving parallel to the optical axis is refracted so that it leaves through the far focal point F. Its outgoing direction depends only on f, not on where the object sits.'
    },
    {
      i: 2, color: C.r2,
      segs: [[[-d, HO], [0, 0]], [[0, 0], [xe, -HO * xe / d]]],
      tip: 'Ray 2: straight through the centre of the lens, undeviated',
      title: 'Ray 2 \u2014 the central ray',
      body: 'A ray aimed at the centre of a thin lens passes straight through: the surfaces are parallel there, so it is not deviated. This ray alone fixes the magnification, h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
    }
  ];
  if (y3 !== null) {
    defs.push({
      i: 3, color: C.r3,
      segs: [[[-d, HO], [0, y3]], [[0, y3], [xe, y3]]],
      tip: 'Ray 3: through the near focal point F \u2192 out parallel to the axis',
      title: 'Ray 3 \u2014 the focal ray',
      body: 'A ray that passes through the near focal point F emerges parallel to the axis \u2014 the exact time-reverse of ray 1. If the object is inside f, it is the backward extension of the ray that passes through F.'
    });
  }

  defs.forEach(function (R) {
    var dim = (state.sel !== 0 && state.sel !== R.i);
    var col = dim ? C.gray : R.color;
    var w = dim ? dimW : (state.sel === R.i ? rayW * 1.55 : rayW);
    R.segs.forEach(function (s) { wseg(gRay, s[0], s[1], col, w); });
    segHeadAtT(gRay, R.segs[0][0], R.segs[0][1], 0.66, col, hs);
    if (R.i === 1) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(1.55, XD[1] - 0.45), col, hs);
    if (R.i === 2) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(2.15, XD[1] - 0.30), col, hs);
    if (R.i === 3) segHeadAtX(gRay, R.segs[1][0], R.segs[1][1], Math.min(1.25, XD[1] - 0.30), col, hs);
    /* virtual-image backward extensions */
    if (O.valid && O.di < 0) {
      var start = (R.i === 1) ? [0, HO] : (R.i === 2 ? [0, 0] : [0, y3]);
      wseg(gRay, start, [O.di, O.hi], col, w * 0.8, true, 0.9);
    }
    if (R.i === 3 && d < 1) wseg(gRay, [-d, HO], [-1, 0], col, w * 0.8, true, 0.8);
    /* hit strips */
    R.segs.forEach(function (s) {
      var l = wseg(gHit, s[0], s[1], '#000', 0.14 * PPF, false, 0);
      if (l) interactive(l, R.tip, R.title, R.body, function () { trigger_raySelect(R.i); });
    });
  });

  /* focal points: dots on the axis, bold italic F labels BELOW the axis (as in the source) */
  [[-1, 'near'], [1, 'far']].forEach(function (p) {
    var dot = gMark.circle(2 * Math.max(2.6, 0.045 * PPF)).fill(C.F).center(plotX(p[0]), plotY(0));
    interactive(dot, 'Focal point F (' + p[1] + ' side) \u2014 one focal length f from the lens',
      'Focal point F',
      'Both focal points lie one focal length f from the lens. Rays arriving parallel to the axis leave through the far F; rays passing through the near F leave parallel to the axis.');
  });

  /* object */
  vArrow(gMark, -d, HO, C.obj, 0.055 * PPF);
  var objHit = gHit.line(plotX(-d), plotY(0), plotX(-d), plotY(HO))
    .stroke({ color: '#000', width: 0.16 * PPF, opacity: 0 });
  interactive(objHit, 'Object, height h\u2092', 'The object',
    'A luminous object of height h\u2092 stands on the axis a distance d\u2092 from the lens. Every point of it radiates in all directions \u2014 we simply trace the three easiest rays from its tip.');

  /* image */
  var imgVisible = O.valid && Math.abs(O.hi) < (YD[1] - 0.1) &&
    O.di > XD[0] + 0.25 && O.di < XD[1] - 0.25;
  if (imgVisible) {
    vArrow(gMark, O.di, O.hi, C.obj, 0.055 * PPF, O.di < 0 ? 0.85 : 1);
    var imgHit = gHit.line(plotX(O.di), plotY(0), plotX(O.di), plotY(O.hi))
      .stroke({ color: '#000', width: 0.16 * PPF, opacity: 0 });
    interactive(imgHit,
      (O.di > 0 ? 'Real, inverted image, height h\u1d62' : 'Virtual, upright image (no light actually there)'),
      'The image',
      O.di > 0
        ? 'All three refracted rays cross here, so this single point is the image. Light really passes through it, so the image is real, and it points downward \u2014 inverted \u2014 with h\u1d62/h\u2092 = \u2212d\u1d62/d\u2092.'
        : 'The refracted rays diverge; only their dashed backward extensions meet. The eye sees an enlarged upright virtual image on the object side \u2014 the magnifying-glass case, with d\u1d62 negative.');
  }

  /* selection ring on the governing marker */
  if (state.sel !== 0) {
    var mx = state.sel === 1 ? 1 : (state.sel === 2 ? 0 : -1);
    gMark.circle(2 * 0.13 * PPF).fill('none')
      .stroke({ color: state.sel === 1 ? C.r1 : (state.sel === 2 ? C.r2 : C.r3), width: 1.8 * K })
      .center(plotX(mx), plotY(0))
      .attr('stroke-dasharray', (0.05 * PPF) + ',' + (0.045 * PPF));
  }

  /* ---------- ray numerals (kept clear of the object arrow) ---------- */
  var labs = [{ i: 1, x: -0.50 * d, y: HO + 0.20, c: C.r1 },
  { i: 2, x: -0.45 * d, y: 0.45 * HO + 0.21, c: C.r2 }];
  if (y3 !== null) {
    if (d > 1) {
      var lx3 = -1 - 0.55 * (d - 1);
      var ly3 = -(HO / (d - 1)) * (lx3 + 1) - 0.20;
      labs.push({ i: 3, x: lx3, y: ly3, c: C.r3 });
    } else {
      labs.push({ i: 3, x: -0.55 * d, y: HO + 0.45 * (y3 - HO) - 0.06, c: C.r3 });
    }
  }
  labs.forEach(function (p) {
    var dim = (state.sel !== 0 && state.sel !== p.i);
    txt(gLab, p.i, plotX(p.x), plotY(p.y),
      { size: fs * 1.22, weight: 'bold', fill: dim ? C.gray : p.c });
  });

  /* F labels drawn last so their haloes sit above every stroke */
  txt(gLab, 'F', plotX(-1.14), plotY(0) + fs * 1.05,
    { size: fs * 1.15, weight: 'bold', italic: true, family: MATHF });
  txt(gLab, 'F', plotX(0.84), plotY(0) + fs * 1.05,
    { size: fs * 1.15, weight: 'bold', italic: true, family: MATHF });

  /* ---------- dimension annotations ---------- */
  if (state.ann) {
    var mg = gLab.group();

    /* h_o, measured at the far left with a dashed leader to the object tip */
    var xho = XD[0] + 0.30;
    mg.line(plotX(xho), plotY(HO), plotX(-d), plotY(HO))
      .stroke({ color: '#9aa0a6', width: 0.8 * K }).attr('stroke-dasharray', (0.035 * PPF) + ',' + (0.035 * PPF));
    vMeasure(mg, xho, HO, 'h', 'o');

    /* f: lens centre \u2192 far focal point, bracket just above the axis;
       label pushed left of where ray 1 crosses the bracket */
    hBracket(mg, 0, 1, 0.30, 'f', '', 0.40);

    var yD1 = -1.75, yD2 = -2.05;
    hBracket(mg, -d, 0, yD1, 'd', 'o');
    if (O.valid) {
      if (O.di < 0) {
        hBracket(mg, Math.max(O.di, XD[0] + 0.25), 0, yD2, 'd', 'i');
      } else {
        hBracket(mg, 0, Math.min(O.di, XD[1] - 0.22), yD1, 'd', 'i');
      }
    }

    /* h_i */
    if (imgVisible) vMeasure(mg, O.di + 0.26, O.hi, 'h', 'i');
  }

  updateReadout(O);
}

/* ---------- UI plumbing ---------- */
function updateReadout(O) {
  var el = document.getElementById('readout');
  if (!el) return;
  if (!O.valid) {
    el.innerHTML = 'd<sub>o</sub> = ' + O.d.toFixed(2) + ' f &nbsp; d<sub>i</sub> &rarr; &infin;<br>Refracted rays are parallel &mdash; no image forms.';
    return;
  }
  var type = O.di > 0 ? 'real, inverted' : 'virtual, upright';
  var size = Math.abs(O.m) > 1 ? 'enlarged' : (Math.abs(O.m) < 1 ? 'reduced' : 'same size');
  var off = (O.di > 0 && O.di > 4.5) ? '<br>(image lies beyond the frame edge)' : '';
  el.innerHTML = '1/d<sub>o</sub> + 1/d<sub>i</sub> = 1/f<br>' +
    'f = 1.00 &nbsp; d<sub>o</sub> = ' + O.d.toFixed(2) + ' f<br>' +
    'd<sub>i</sub> = ' + O.di.toFixed(2) + ' f<br>' +
    'm = &minus;d<sub>i</sub>/d<sub>o</sub> = ' + O.m.toFixed(2) + '<br>' + type + ', ' + size + off;
}

function update_objectDistance(v) { state.d = +v; render(); }
function toggle_annotations(on) { state.ann = !!on; render(); }
function trigger_raySelect(n) {
  state.sel = (state.sel === n && n !== 0) ? 0 : n;
  syncRayButtons();
  render();
}
function syncRayButtons() {
  for (var i = 0; i <= 3; i++) {
    var b = document.getElementById('rayBtn' + i);
    if (b) b.className = (state.sel === i) ? 'active' : '';
  }
}

var STEPS = [
  {
    title: 'The measured figure',
    narration: 'The full textbook figure: an object of height h\u2092, a fat biconvex lens with its dashed principal plane, focal points F one focal length f on each side, brackets for f, d\u2092 and d\u1d62, and the inverted image of height h\u1d62.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Three rays, three rules',
    narration: 'Rays 1, 2 and 3 all leave the same point at the object\u2019s tip. Click any one (in the figure or with the buttons) to isolate it: parallel-then-through-F, straight-through-the-centre, or through-F-then-parallel.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Strip the annotations',
    narration: 'Hide the brackets and height arrows and only the rays remain \u2014 yet they still cross at exactly the same point. The image location is a consequence of the geometry, not of the labels.',
    state: { objectDistance: 2.5, annotations: 'Hidden' }
  },
  {
    title: 'Bring the measurements back',
    narration: 'Restore the overlay and read the numbers: h\u1d62/h\u2092 equals \u2212d\u1d62/d\u2092, and the three distances satisfy 1/d\u2092 + 1/d\u1d62 = 1/f.',
    state: { objectDistance: 2.5, annotations: 'Shown' }
  },
  {
    title: 'Push the object far away',
    narration: 'With the object far from the lens the rays converge just beyond the far focal point: d\u1d62 shrinks toward f and the inverted image becomes small.',
    state: { objectDistance: 5, annotations: 'Shown' }
  },
  {
    title: 'Slide it toward the focal point',
    narration: 'As d\u2092 approaches f the refracted rays become nearly parallel, d\u1d62 shoots off to the right and the inverted image grows enormous.',
    state: { objectDistance: 1.15, annotations: 'Shown' }
  },
  {
    title: 'Inside the focal point',
    narration: 'Closer than f, the refracted rays diverge; their dashed backward extensions meet at an upright, magnified virtual image on the object side \u2014 the magnifying-glass case, with d\u1d62 now negative.',
    state: { objectDistance: 0.6, annotations: 'Shown' }
  }
];

function setStep(i) {
  state.step = (i + STEPS.length) % STEPS.length;
  var s = STEPS[state.step];
  document.getElementById('objectDistanceInput').value = s.state.objectDistance;
  document.getElementById('objectDistanceVal').value = (+s.state.objectDistance).toFixed(2);
  state.d = +s.state.objectDistance;
  var ann = (s.state.annotations !== 'Hidden');
  document.getElementById('annotationsInput').checked = ann;
  state.ann = ann;
  state.sel = 0; syncRayButtons();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + '/' + STEPS.length + '  ' + s.title;
  render();
}
function nextStep() { setStep(state.step + 1); }
function prevStep() { setStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });

setStep(0);
window.__markRendered();
